tool.command:

  ln -f -s ${input_ligands_sdf_path} ${input_ligands_sdf_path}_`echo $$`.${input_ligands_sdf_path.ext};

  ln -f -s ${input_receptor_pdbqt_path} ${input_receptor_pdbqt_path}_`echo $$`.${input_receptor_pdbqt_path.ext};

  ln -f -s ${input_site_coords_path} ${input_site_coords_path}_`echo $$`.${input_site_coords_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

smina_run

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__cpu__dq__:${properties.cpu},__dq__exhaustiveness__dq__:${properties.exhaustiveness},__dq__num_modes__dq__:${properties.num_modes},__dq__min_rmsd_filter__dq__:${properties.min_rmsd_filter},__dq__energy_range__dq__:${properties.energy_range},__dq__binary_path__dq__:__dq__${properties.binary_path}__dq__,__dq__scoring__dq__:__dq__${properties.scoring}__dq____cc____cc__'
  #end if

  #if str($input_ligands_sdf_path) != 'None':
    --input_ligands_sdf_path ${input_ligands_sdf_path}_`echo $$`.${input_ligands_sdf_path.ext}
  #end if

  #if str($input_receptor_pdbqt_path) != 'None':
    --input_receptor_pdbqt_path ${input_receptor_pdbqt_path}_`echo $$`.${input_receptor_pdbqt_path.ext}
  #end if

  #if str($input_site_coords_path) != 'None':
    --input_site_coords_path ${input_site_coords_path}_`echo $$`.${input_site_coords_path.ext}
  #end if


  --output_sdf_path $outname_output_sdf_path

  --output_log_path $outname_output_log_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_ligands_sdf_path}_`echo $$`.${input_ligands_sdf_path.ext};

  rm -f ${input_receptor_pdbqt_path}_`echo $$`.${input_receptor_pdbqt_path.ext};

  rm -f ${input_site_coords_path}_`echo $$`.${input_site_coords_path.ext};


  if test -f $outname_output_sdf_path; then mv $outname_output_sdf_path $output_sdf_path; fi;

  if test -f $outname_output_log_path; then mv $outname_output_log_path $output_log_path; fi;
